                            rule: "PROPORTIONAL" | "PERCENT" | "FIXED" | "NONE";
                            /** @description Why some member figures are null: NOT_ALLOCATED (rule NONE) reports consumption only, TRACKED_AT_FUND_LEVEL (SHARED_FUND) leaves contribution and gap to the fund, INVALID_ALLOCATION assigns nobody; null when the line is allocated, valid and tracked per member. */
